// Parse the response JSON
const responseData = pm.response.json();

// Check if the embedding exists in the response
if (responseData && responseData.embedding) {
    // Convert the array to a JSON string so it can be stored as a variable
    const embeddingString = JSON.stringify(responseData.embedding);
    
    // Store it as a collection variable (accessible across the entire collection)
    pm.collectionVariables.set("resumeEmbedding", embeddingString);
    
    // Alternatively, use pm.environment.set("resumeEmbedding", embeddingString); for an environment variable
    
    console.log("resumeEmbedding successfully saved!");
} else {
    console.log("Embedding not found in response.");
}
